namespace ghidra.features.bsim.query.protocol;

using ghidra.features.bsim.query;
using ghidra.features.bsim.query.description;

public class NullStaging : StagingManager {

	/* @Override */
	public BSimQuery<object> getQuery() {
		return globalQuery;
	}

	/* @Override */
	public bool initialize(BSimQuery<object> q)
    {
		globalQuery = q;
		totalsize = 0;
		queriesmade = 0;
		
		DescriptionManager imanage = q.getDescriptionManager();
		if (imanage == null)
			return true;

		totalsize = imanage.numFunctions();
		return (totalsize != 0);	// Is there any data at all for an initial stage
	}

	/* @Override */
	public bool nextStage() {
		queriesmade = totalsize;
		return false;		// There is always only one stage
	}
}
